# --- Security Tests --------------------------------------------------------
class TestSecurity:
    """Security-focused tests for XSS and injection prevention."""

    @pytest.mark.parametrize("vector", XSS_VECTORS)
    def test_all_xss_vectors_are_sanitized(self, component_module, vector):
        """Comprehensive XSS vector testing."""
        sanitized = component_module.sanitizeValue(vector)
        # No executable JavaScript should remain
        dangerous_patterns = [
            r'<script', r'on\w+\s*=', r'javascript:', r'alert\s*\(',
            r'<iframe', r'<svg', r'<img[^>]*onerror', r'drop\s+table',
            r'<!--.*?-->', r'<style', r'<math', r'<mglyph', r'<mtext'
        ]
        for pattern in dangerous_patterns:
            assert not re.search(pattern, sanitized, re.IGNORECASE), \
                f"Pattern '{pattern}' found in sanitized output: {sanitized}"

    def test_event_handler_attributes_stripped(self, component_module):
        """Event handler attributes should be stripped from HTML."""
        html = '<div onclick="alert(1)" onmouseover="steal()">content</div>'
        sanitized = component_module.sanitizeValue(html)
        assert "onclick" not in sanitized.lower()
        assert "onmouseover" not in sanitized.lower()

    def test_sql_injection_attempts_neutralized(self, component_module):
        """SQL injection patterns should not pass through."""
        sql_vectors = [
            "'; DROP TABLE users;--",
            "1 OR 1=1",
            "UNION SELECT * FROM users",
            "'; EXEC xp_cmdshell('dir');--"
        ]
        for vector in sql_vectors:
            sanitized = component_module.sanitizeValue(vector)
            assert "DROP TABLE" not in sanitized.upper()
            assert "UNION SELECT" not in sanitized.upper()

    def test_doppurify_bypass_attempts(self, component_module):
        """Attempts to bypass DOMPurify should be caught."""
        bypass_vectors = [
            "<svg><g/onload=alert(2)//<p>",
            "<math><mtext><table><mglyph><style><!--</style><img title=\"--><img src=1 onerror=alert(1)>\">",
            "<a href=\"javas&#99;ript:alert(1)\">click</a>",
            "<img src=x onerror=\"&#97;lert(1)\">",
            "<svg><script>alert(1)</script></svg>"
        ]
        for vector in bypass_vectors:
            sanitized = component_module.sanitizeValue(vector)
            assert "alert" not in sanitized.lower(), f"Bypass vector not sanitized: {vector}"


